class ActivationBlock {HHOOK hook_=nullptr;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int code,WPARAM wp,LPARAM lp)->LRESULT{return code==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,code,wp,lp);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate alignment fixture");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
DocumentState Source(){Image image;image.Create(640,480);DocumentState state;state.base=std::make_shared<Image>(std::move(image));for(auto r:{RECT{30,30,90,70},RECT{150,90,190,140},RECT{300,210,380,270},RECT{440,330,490,390}}){Annotation a;a.tool=Tool::Rectangle;a.rect=r;a.points={{r.left,r.top},{r.right,r.bottom}};a.text=L"keep";state.objects.push_back(a);}return state;}
DocumentState DragSource(){auto state=Source();state.objects.resize(3);state.objects[1].rect={200,150,260,210};state.objects[1].points={{200,150},{260,210}};state.objects[2].rect={400,300,450,350};state.objects[2].points={{400,300},{450,350}};return state;}
LONG Anchor(RECT r,int action){switch(action){case 0:return r.left;case 1:return r.left+(r.right-r.left)/2;case 2:return r.right;case 3:return r.top;case 4:return r.top+(r.bottom-r.top)/2;default:return r.bottom;}}
template<class F>bool Reject(F action){try{action();return false;}catch(const std::exception&){return true;}}
void Core(Check check){const auto source=Source();const composition::Indices selected{0,1,2};
    for(int action=0;action<6;++action){const auto arranged=ArrangeObjects(source,selected,static_cast<Arrange>(action));const auto expected=Anchor(composition::Bounds(source,selected),action);bool aligned=true,preserved=arranged.base==source.base;
        for(int i:selected){const auto& a=arranged.objects[i];const auto& b=source.objects[i];aligned=aligned&&Anchor(a.rect,action)==expected;preserved=preserved&&a.rect.right-a.rect.left==b.rect.right-b.rect.left&&a.rect.bottom-a.rect.top==b.rect.bottom-b.rect.top&&a.text==b.text&&a.width==b.width&&a.fontSize==b.fontSize&&a.points[0].x==a.rect.left&&a.points[0].y==a.rect.top;}
        check(aligned&&preserved&&EqualRect(&arranged.objects[3].rect,&source.objects[3].rect),"all six alignments preserve source/styles/points and unselected objects");
        const auto canvas=ArrangeObjects(source,selected,static_cast<Arrange>(action),true);check(Anchor(canvas.objects[0].rect,action)==Anchor({0,0,640,480},action)&&Anchor(canvas.objects[2].rect,action)==Anchor({0,0,640,480},action),"explicit canvas reference applies to every selected unit");}
    const auto single=ArrangeObjects(source,{0},Arrange::Right);check(single.objects[0].rect.right==640&&single.objects[0].rect.top==30,"a single object aligns to canvas without scaling");
    const auto horizontal=ArrangeObjects(source,selected,Arrange::Horizontal);check(horizontal.objects[1].rect.left==175&&horizontal.objects[1].rect.left-horizontal.objects[0].rect.right==horizontal.objects[2].rect.left-horizontal.objects[1].rect.right&&EqualRect(&horizontal.objects[0].rect,&source.objects[0].rect)&&EqualRect(&horizontal.objects[2].rect,&source.objects[2].rect),"horizontal equal gaps retain differently sized outer objects");
    const auto vertical=ArrangeObjects(source,selected,Arrange::Vertical);check(vertical.objects[1].rect.top==115&&vertical.objects[1].rect.top-vertical.objects[0].rect.bottom==vertical.objects[2].rect.top-vertical.objects[1].rect.bottom,"vertical equal gaps retain object sizes and outer positions");
    auto rounded=source;rounded.objects[2].rect.right=381;const auto rounding=ArrangeObjects(rounded,selected,Arrange::Horizontal);check(std::abs((rounding.objects[1].rect.left-rounding.objects[0].rect.right)-(rounding.objects[2].rect.left-rounding.objects[1].rect.right))<=1&&rounding.objects[2].rect.left==300,"fractional gaps round within one pixel without drifting the last unit");
    auto grouped=source;grouped.objects[0].group=grouped.objects[1].group=7;check(SelectionUnits(grouped,{0,2}).size()==2&&SelectionUnits(grouped,{0})[0]==composition::Indices({0,1}),"partial group selection expands into one indivisible alignment unit");
    const auto groupRight=ArrangeObjects(grouped,{0},Arrange::Right);check(groupRight.objects[1].rect.right==640&&groupRight.objects[1].rect.left-groupRight.objects[0].rect.left==120&&groupRight.objects[0].group==7&&groupRight.objects[0].points[0].x==groupRight.objects[0].rect.left,"single group canvas alignment translates all members without changing internal offsets or metadata");
    check(Reject([&]{ArrangeObjects(grouped,{0,2},Arrange::Horizontal);}),"two logical units cannot be distributed even if the group has two members");
    auto locked=source;locked.objects[1].locked=true;check(Reject([&]{ArrangeObjects(locked,selected,Arrange::Left);})&&locked.objects[0].rect.left==30,"locked mixed selection is rejected transactionally");
    check(Reject([&]{ArrangeObjects(source,{99},Arrange::Left);})&&Reject([&]{ArrangeObjects(source,{0,1},Arrange::Vertical);}),"stale selection and insufficient distribution counts fail safely");
    auto crowded=source;for(int i:selected)crowded.objects[i].rect={0,0,100,100};check(Reject([&]{ArrangeObjects(crowded,selected,Arrange::Horizontal);})&&crowded.objects[1].rect.left==0,"negative equal-gap layouts are rejected instead of overlapping or partially moving units");
    auto extreme=source;extreme.objects[0].points[0].x=1000000;check(Reject([&]{ArrangeObjects(extreme,{0},Arrange::Right);})&&extreme.objects[0].rect.left==30,"out-of-range point translation cannot partly modify the input");
    check(Reject([&]{MoveObject(extreme.objects[0],20,0);})&&MoveObject(source.objects[0],5,-5).rect.top==25,"single-object movement uses the same bounded transactional translation");
    check(!PositionsChanged(source,source,selected)&&PositionsChanged(source,horizontal,selected),"geometry comparison distinguishes actual changes from no-op arrangements");
    const auto targets=BuildTargets(source,{0});check(std::is_sorted(targets.x.begin(),targets.x.end())&&std::find(targets.x.begin(),targets.x.end(),30)==targets.x.end()&&std::find(targets.x.begin(),targets.x.end(),320)!=targets.x.end(),"cached targets include canvas centers and exclude the entire moving selection");
    const auto groupTargets=BuildTargets(grouped,{0});check(std::find(groupTargets.x.begin(),groupTargets.x.end(),150)==groupTargets.x.end(),"cached targets exclude every member of a partly specified moving group");
    const Targets simple{{0,100,200},{0,120,240}};const auto snap=SnapMove({96,116,136,146},simple,6);check(snap.rect.left==100&&snap.rect.top==120&&snap.x==100&&snap.y==120&&snap.rect.right-snap.rect.left==40,"nearest independent axis snapping preserves dimensions and reports exact guides");
    const auto outside=SnapMove({92,112,132,142},simple,6);check(outside.rect.left==92&&outside.rect.top==112&&!outside.x&&!outside.y,"out-of-tolerance movement does not snap or advertise guides");
    check(Reject([&]{SnapMove({0,0,20,20},simple,-1);})&&Reject([&]{SnapMove({0,0,20,20},simple,std::numeric_limits<double>::infinity());}),"invalid snapping tolerances fail before coordinate conversion");
    auto many=source;many.objects.clear();for(int i=0;i<10000;++i){Annotation a;a.rect={i,10,i+10,20};many.objects.push_back(a);}const auto start=std::chrono::steady_clock::now();const auto cached=BuildTargets(many,{0});for(int i=0;i<1000;++i)SnapMove({i,50,i+20,70},cached,6);check(cached.x.size()<=30003&&cached.y.size()<=30003&&std::chrono::steady_clock::now()-start<std::chrono::seconds(8),"10000-object targets are bounded/cached and repeated queries avoid full rescans");
}
