        CMenu top;top.CreatePopupMenu();for(UINT id=ObjectAlignLeft;id<=SnapObjects;++id)top.AppendMenu(MF_STRING,EditorMenuId(id),Tr(Text::ObjectsGroup));workspace->SendMessage(WM_INITMENUPOPUP,reinterpret_cast<WPARAM>(top.m_hMenu),0);check((top.GetMenuState(EditorMenuId(ObjectAlignLeft),MF_BYCOMMAND)&MF_GRAYED)&&!(top.GetMenuState(EditorMenuId(SnapObjects),MF_BYCOMMAND)&MF_CHECKED),"native top menu refresh shows disabled alignment and unchecked snapping");
        for(int action=0;action<6;++action){Reset(p,Source());p->SetSelection({0,1,2});const auto revision=p->revision_;workspace->SendMessage(WM_COMMAND,EditorMenuId(ObjectAlignLeft+action));Wait(p);check(p->revision_==revision+1&&Anchor(p->document_.State().objects[0].rect,action)==Anchor(p->document_.State().objects[2].rect,action),"native top Edit aliases apply each alignment in one Undo step");p->SendMessage(WM_COMMAND,Undo);Wait(p);check(p->document_.State().objects[1].rect.left==150&&p->document_.State().objects[1].rect.top==90,"one native Undo restores the entire arrangement");}
