        Reset(p);Mouse(p,WM_LBUTTONDOWN,At(p,60,50));Mouse(p,WM_MOUSEMOVE,At(p,226,166));check(p->draft_.rect.left==196&&!p->snapX_,"snapping off preserves precise raw drag coordinates");Mouse(p,WM_LBUTTONUP,At(p,226,166));Wait(p);
