            auto large=DragSource();large.objects.resize(2);large.objects[0].rect={20,20,140,120};large.objects[0].points={{20,20},{140,120}};large.objects[1].rect={300,200,420,300};large.objects[1].points={{300,200},{420,300}};Reset(p,std::move(large));
            p->ZoomTo(zoom);p->offsetX_=zoom==2?17:0;p->offsetY_=zoom==2?19:0;p->ClampViewport();const auto tolerance=Px(p->m_hWnd,6)/zoom;int snapGap=std::max(2,static_cast<int>(tolerance)-2);snapGap-=snapGap%2;
