            check(p->dragging_&&p->handle_<0&&p->draft_.rect.left==300&&p->draft_.rect.right==420&&p->snapX_==300,"screen-scaled nearest-axis snapping respects bilingual DPI, zoom and pan without hitting resize nodes");
